defmodule Extreme.Mixfile do
  use Mix.Project

  def project do
    [
      app: :extreme,
      version: "1.2.0",
      elixir: "~> 1.16",
      elixirc_paths: _elixirc_paths(Mix.env()),
      source_url: "https://github.com/exponentially/extreme",
      description: """
      Elixir TCP client for EventStore.
      """,
      package: _package(),
      docs: _docs(),
      start_permanent: Mix.env() == :prod,
      test_coverage: [
        # generated by scripts/gen_messages.sh from include/event_store.proto
        ignore_modules: [~r/^Extreme\.Messages\./],
        summary: [
          threshold: 85.0
        ]
      ],
      deps: _deps()
    ]
  end

  def cli do
    [
      preferred_envs: [
        vcr: :test,
        "vcr.delete": :test,
        "vcr.check": :test,
        "vcr.show": :test
      ]
    ]
  end

  def application do
    [
      extra_applications: [:logger, :inets]
    ]
  end

  # Specifies which paths to compile per environment.
  defp _elixirc_paths(:test), do: ["lib", "test/support"]
  defp _elixirc_paths(_), do: ["lib"]

  defp _deps do
    [
      {:protobuf, "~> 0.17.1"},
      {:telemetry, "~> 0.4 or ~> 1.0"},
      # needed when connecting to EventStore cluster (node_type: :cluster | :cluster_dns)
      {:jason, "~> 1.1", optional: true},

      # testing
      {:exvcr, "~> 0.10", only: :test},
      {:ex_doc, ">= 0.0.0", only: :dev}
      # {:earmark, "~> 1.2", only: :test},
      # {:inch_ex, "~> 1.0", only: :test},
      # {:excoveralls, "~> 0.9", only: :test},
    ]
  end

  # Generated message modules are hidden, so references to them stay plain code.
  defp _docs do
    [
      filter_modules: fn module, _metadata -> module != Extreme.Messages.Compat end,
      skip_code_autolink_to: &String.starts_with?(&1, "Extreme.Messages."),
      skip_undefined_reference_warnings_on: ["c:Extreme.ListenerWithBackPressure.process_push/3"]
    ]
  end

  defp _package do
    [
      files: ["lib", "mix.exs", "README*", "LICENSE*", "include"],
      maintainers: ["Milan Burmaja"],
      licenses: ["MIT"],
      links: %{"GitHub" => "https://github.com/exponentially/extreme"}
    ]
  end
end
